package com.sociax.app.ui.theme

import androidx.compose.runtime.Composable
import androidx.compose.runtime.ReadOnlyComposable
import androidx.compose.runtime.compositionLocalOf

/** The five languages of the plan (section 9). English is the default. */
enum class Lang(val code: String, val label: String) {
    EN("en", "English"), FR("fr", "Français"), ZH("zh", "中文"), KO("ko", "한국어"), RU("ru", "Русский");

    companion object {
        fun fromCode(code: String?): Lang = values().firstOrNull { it.code == code } ?: EN
    }
}

val LocalLang = compositionLocalOf { Lang.EN }

/** Translated text for the current language. Missing keys fall back to English, then to the key itself. */
@Composable
@ReadOnlyComposable
fun tr(key: String): String = Strings.get(LocalLang.current, key)

/** Same as tr() but fills in values: %s for text, %d for numbers. */
@Composable
@ReadOnlyComposable
fun trf(key: String, vararg args: Any): String = String.format(Strings.get(LocalLang.current, key), *args)

/** Report reason shown in the chosen language (the English word is what is sent to the server). */
@Composable
@ReadOnlyComposable
fun reasonLabel(r: String): String = when (r) {
    "Spam" -> tr("reason_spam")
    "Harassment" -> tr("reason_harassment")
    "Inappropriate content" -> tr("reason_inappropriate")
    else -> r
}

private fun e(en: String, fr: String, zh: String, ko: String, ru: String) = listOf(en, fr, zh, ko, ru)

